    if (!sheet) return;
    this.retiring.set(p.id);
    this.api.retire(sheet.id, p.id, from === '' ? null : from).subscribe({
      next: (retired) => {
        this.retiring.set(null);
        this.people.update((list) => list.map((q) => (q.id === retired.id ? retired : q)));
      },
      error: () => {
        this.retiring.set(null);
