            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return watches.list(sheetId, user.trim()).stream().map(Watch::getPersonId).toList();
    }

    @PutMapping("/people/{id}/watch")
    public WatchView set(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @PathVariable long id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody WatchForm request) {
        return new WatchView(id, watches.set(sheetId, user.trim(), id, request.watched()));
    }
}
